            <h2>Secure PDF workflow for Government</h2>
            <p>Use case: FOIA / CUI — Clerk redacts CUI from release PDF, watermarks DRAFT, and protects the volume before SAM upload.</p>
            <ol>
            <li><a href="/pdf/redaction">Redact</a> sensitive content — flatten so hidden text cannot be recovered</li>
            <li><a href="/pdf/watermark">Watermark</a> DRAFT or CONFIDENTIAL until cleared for release</li>
            <li><a href="/pdf/password">Password-protect</a> with AES-256 — share the passphrase on a separate channel</li>
            <li>Log version and retention class before external share</li>
            </ol>
            <p><a href="/guides/compress-pdf-for-government">Compress workflow</a> · <a href="/guides/document-retention-pdf">Retention</a> · <a href="/guides/pdf-version-control-best-practices">Version control</a>.</p>
            <p>Tool: <a href="/pdf/redaction">/pdf/redaction</a></p>
            <div class="rp-mid-cta alert alert-primary my-4"><strong>Start workflow</strong> <a href="/pdf/redaction" class="alert-link fw-semibold">Redact PDF →</a></div>
            
            <h2>Audit trail discipline</h2>
            <p>Compliance PDFs need version numbers, approver initials, and immutable storage — not WhatsApp forwards of draft redlines. Filename convention: <code>Invoice-2026-0142-v3-APPROVED.pdf</code>. Store hash or checksum for tax and GDPR disputes.</p>

            <h2>Cross-border note</h2>
            <p>India GST rules differ from EU VAT — do not reuse invoice templates across jurisdictions. Country guides: <a href="/guides/invoice-generator-india">India</a> · <a href="/guides/invoice-generator-uk">UK</a> · <a href="/guides/invoice-generator-usa">USA</a>.</p>

