            <h2>Secure-share checklist</h2>
            <ol>
            <li>Redact and flatten before any external share — hidden layers leak data</li>
            <li>Watermark DRAFT/CONFIDENTIAL until release is approved</li>
            <li>AES-256 password — never email the passphrase with the file</li>
            <li>Log version, approver, and retention class for the audit trail</li>
            </ol>
            
            
            <h2>Archival QA checklist</h2>
            <ol>
            <li>Right standard selected for use case</li>
            <li>veraPDF or prepress validation if required</li>
            <li>Metadata scrubbed before external publish</li>
            <li>Checksum logged on ingest</li>
            <li>Retention class assigned in records system</li>
            <li>Sample open test scheduled annually</li>
            </ol>
